window.ECLIPSE_DEMO = { async request(path, options) {
  if(window.ECLIPSE_SERVER_MODE){const response=await fetch('/api/v1/'+path,options);const data=await response.json();if(!response.ok)throw Error(data.message||'Não foi possível carregar.');return data;}
  const catalog=window.ECLIPSE_PUBLIC_ADMIN?.products()||demoProducts;
  if (path === 'categories') {
    const active=new Set(catalog.flatMap(p=>(p.categoryKeys||[])));
    return (window.ECLIPSE_PUBLIC_ADMIN?.categories()||demoCategories).filter(category=>active.has(category.slug));
  }
  if (path === 'quote') {
    const input = JSON.parse(options?.body || '{}');
    if (!Array.isArray(input.items) || !input.items.length || input.items.length > 100) throw Error('Carrinho inválido.');
    const seen = new Set();
    const items = input.items.map(item => {
      const product = catalog.find(p => p.id === item.id);
      const variant = product?.variants.find(v => v.id === item.variantId);
      const choices = item.basketChoices;
      const options = product?.basketOptions;
      let label = variant?.label;
      if(options){
        if(!Array.isArray(choices)||choices.length!==options.length)throw Error('Escolha um tamanho para cada produto do combo.');
        label=options.map((option,index)=>{
          const chosen=option.variants.find(v=>v.id===choices[index]);
          if(!chosen)throw Error('Uma combinação do combo está indisponível.');
          return option.name+' ('+chosen.label+')';
        }).join('; ');
      }
      const key = `${item.id}:${item.variantId}:${options?choices.join(','):''}`;
      if (seen.has(key)) throw Error('Combinação duplicada no carrinho.');
      seen.add(key);
      if (!variant || !variant.available || !Number.isInteger(item.quantity) || item.quantity < 1 || item.quantity > 99) throw Error('Quantidade indisponível. Revise a disponibilidade da combinação escolhida.');
      return {id:product.id,variantId:variant.id,name:product.name,sku:product.sku,label,quantity:item.quantity,price:variant.price,max:variant.max};
    });
    return {items,total:Math.round(items.reduce((sum,i)=>sum+i.price*i.quantity,0)*100)/100,phone:window.ECLIPSE_PUBLIC_ADMIN?.settings().phone||window.ECLIPSE_CONFIG.phone};
  }
  if (path.startsWith('products/')) {
    const product=catalog.find(p=>p.id===Number(path.split('/')[1]));
    if (!product) throw Error('Produto indisponível.');
    return product;
  }
  const q=new URLSearchParams(path.split('?')[1]);
  const categoryKeys=(q.get('category')||'').split(',').filter(Boolean);
  const searchKey=value=>String(value??'').normalize('NFD').replace(/\p{Diacritic}/gu,'').replace(/[^\p{L}\p{N}]/gu,'').toLowerCase();
  const search=searchKey(q.get('search'));
  let products=catalog.filter(p=>(!q.get('audience')||p.audiences.includes(q.get('audience')))&&(!categoryKeys.length||categoryKeys.some(key=>p.categoryKeys.includes(key)))&&(!search||searchKey([p.name,p.brand,p.sku].join(' ')).includes(search)));
  if(q.get('scope')==='offers'){
    products=products.filter(p=>p.sale);
    const type=q.get('offerType');
    if(type==='promotions'||type==='combos')products=products.filter(p=>Boolean(p.basket)===(type==='combos'));
  }
  if(q.get('scope')==='regular') products=products.filter(p=>!p.sale);
  if(q.get('scope')==='new') products=products.filter(p=>!p.basket&&Date.now()/1000-p.arrivedAt>=0&&Date.now()/1000-p.arrivedAt<30*86400);
  if(q.get('stock')==='1') products=products.filter(p=>p.available);
  if(q.get('scope')==='offers'){
    products.sort((a,b)=>(b.offerAt||b.arrivedAt||0)-(a.offerAt||a.arrivedAt||0)||b.id-a.id);
    if(q.get('order')==='price')products.sort((a,b)=>a.price-b.price);
  }else products.sort((a,b)=>b.arrivedAt-a.arrivedAt);
  const perPage=Math.min(24,Math.max(1,Number(q.get('limit'))||24)), page=Math.max(1,Number(q.get('page'))||1);
  return {products:products.slice((page-1)*perPage,page*perPage),total:products.length,pages:Math.ceil(products.length/perPage)};
}};
